import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long a = in.nextLong();
        long n = in.nextLong();
        long x = 1;
        while ((a + x) % n != 1) {
            x++;
        }
        System.out.println(x);
    }
}

